SELECT

FROM dish d
WHERE d.status = 'ON_SALE'
  AND d.audit_status = 'APPROVED'
  AND d.kitchen_id = #{kitchenId}

      AND d.category_id = #{categoryId}


      AND d.is_recommend = #{recommend}


      AND (d.name ILIKE CONCAT('%', #{keyword}, '%')
           OR d.subtitle ILIKE CONCAT('%', #{keyword}, '%'))

/* @conditionSql */
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM dish d
WHERE d.status = 'ON_SALE'
  AND d.audit_status = 'APPROVED'
  AND d.kitchen_id = #{kitchenId}

      AND d.category_id = #{categoryId}


      AND d.is_recommend = #{recommend}


      AND (d.name ILIKE CONCAT('%', #{keyword}, '%')
           OR d.subtitle ILIKE CONCAT('%', #{keyword}, '%'))

SELECT

FROM dish d
WHERE 1 = 1

      AND d.kitchen_id = #{kitchenId}


      AND d.category_id = #{categoryId}


      AND d.status = #{status}


      AND d.audit_status = #{auditStatus}


      AND d.name ILIKE CONCAT('%', #{keyword}, '%')

/* @conditionSql */
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM dish d
WHERE 1 = 1

      AND d.kitchen_id = #{kitchenId}


      AND d.category_id = #{categoryId}


      AND d.status = #{status}


      AND d.audit_status = #{auditStatus}


      AND d.name ILIKE CONCAT('%', #{keyword}, '%')

SELECT

FROM dish d
WHERE d.kitchen_id = #{kitchenId}

      AND d.status = #{status}


      AND d.audit_status = #{auditStatus}


      AND d.name ILIKE CONCAT('%', #{keyword}, '%')

ORDER BY d.sort_order ASC, d.last_modify_time DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM dish d
WHERE d.kitchen_id = #{kitchenId}

      AND d.status = #{status}


      AND d.audit_status = #{auditStatus}


      AND d.name ILIKE CONCAT('%', #{keyword}, '%')

